    [InitializeOnLoad] public static class WardrobeR22Preview {
        const string Key="WardrobeR22Preview";
        static WardrobeR22Preview(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);UnityEngine.Object.FindAnyObjectByType<RiichiClient>().gameObject.AddComponent<WardrobeR22Capture>();}};}
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Bootstrap(){if(!SessionState.GetBool(Key,false))return;WardrobePackService.RootOverride=SessionState.GetString(Key+"Root","");WardrobePackService.RespectPreviewAvailability=true;WardrobePackService.ResetForReview();}
        public static void Run(){string repo=Environment.GetEnvironmentVariable("YUNJIAN_R22_REPO")??Path.GetFullPath(".."),fixture=Environment.GetEnvironmentVariable("YUNJIAN_R22_FIXTURE_ROOT");string root=repo+"/build/wardrobe-r22/clients/"+Guid.NewGuid().ToString("N");if(!string.IsNullOrEmpty(fixture)){root=Path.GetFullPath(fixture);if(!root.StartsWith(Path.GetFullPath(repo+"/build/wardrobe-r22/clients/").TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Review fixture path is outside the isolated clients folder");}SessionState.SetString(Key+"Root",root);AssetDatabase.Refresh();EditorSceneManager.OpenScene("Assets/Scenes/Table.unity");SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
    }
