            client=GetComponent<RiichiClient>();table=GetComponent<TableRenderer>();fx=GetComponent<TableEffects>();service=WardrobePackService.Instance;ui=WardrobeResourceUi.Current;
            oldDynamic=AppPreferences.DynamicOutfits;oldInset=AppPreferences.ScreenInset;CharacterRoster.BeginPreview();WardrobeSelection.BeginPreview();AppPreferences.SetDynamicOutfits(false);AppPreferences.SetInset(0);AudioListener.pause=true;Application.targetFrameRate=60;
            client.BeginLobbyValidation("wardrobe-r22");client.SessionPreviewOnly=true;GetComponent<ResourceRoomCoordinator>().enabled=false;
            var tasks=new Stack<IEnumerator>();tasks.Push(Run());
            while(tasks.Count>0){object next;try{var task=tasks.Peek();if(!task.MoveNext()){tasks.Pop();continue;}next=task.Current;if(next is IEnumerator child){tasks.Push(child);continue;}}catch(Exception e){File.WriteAllText(output+"/failed.txt",e.ToString());File.WriteAllText(output+"/partial-checks.json",JsonUtility.ToJson(report,true));Debug.LogException(e);Cleanup();EditorApplication.Exit(1);yield break;}yield return next;}
            Check(errors.Count==0,"No unexpected Unity runtime errors");File.WriteAllText(output+"/checks"+(mode=="all"?"":"-"+mode)+".json",JsonUtility.ToJson(report,true));Cleanup();Debug.Log("WARDROBE R22 RUNTIME PASS mode="+mode+" checks="+report.checks.Count+" cases="+report.cases+" frames="+report.frames);EditorApplication.Exit(0);
        }
        void Cleanup(){caption=null;source?.Dispose();relay?.Dispose();if(encoder!=null){try{pipe?.Close();encoder.WaitForExit(5000);}catch{}encoder.Dispose();encoder=null;}fx.Reset();fx.ValidationFreeze=false;fx.ValidationSequentialClock=false;Time.captureFramerate=0;WardrobePackService.ResetForReview();WardrobeSelection.EndPreview();CharacterRoster.EndPreview();AppPreferences.SetDynamicOutfits(oldDynamic);AppPreferences.SetInset(oldInset);AudioListener.pause=false;Application.logMessageReceived-=Log;}
