        IEnumerator Until(Func<bool> ready,string label,float seconds=90){float deadline=Time.realtimeSinceStartup+seconds;while(!ready()){if(Time.realtimeSinceStartup>deadline)throw new Exception("Timeout: "+label+" "+service.Error);yield return null;}}
        IEnumerator Size(){var view=EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));view.GetType().GetMethod("SetCustomResolution",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(view,new object[]{new Vector2(1746,810),"Wardrobe R22"});yield return Wait(8);}
