        IEnumerator Press(string id){ui.ReviewPress=id;yield return Wait(5);Check(ui.ReviewPress==null,"Wardrobe resource control: "+id);}
        string Bundle(WardrobePackRecord p)=>repo+"/build/wardrobe-r22/packs/windows/"+p.file;
        string Url(WardrobePackRecord p,CharacterPackShareServer server)=>"http://127.0.0.1:"+server.Port+"/packs/"+p.sha256+"?ticket="+server.Ticket;
        IEnumerator Download(string id){service.DownloadItem(id);yield return Until(()=>!service.Busy,"Download "+id);Check(string.IsNullOrEmpty(service.Error),"Download succeeds: "+id+" "+service.Error);Check(WardrobePackService.Installed(id),"Receipt and dependency closure installed: "+id);}
