        IEnumerator DownloadFlow(){
            source=new CharacterPackShareServer{Enabled=true,ReviewChunkDelayMs=18};source.SetEntries(WardrobePackService.All.Where(p=>!p.builtin).Select(p=>new CharacterPackShareServer.Entry{key=p.key,hash=p.sha256,bytes=p.bytes,path=Bundle(p),wardrobe=true}));service.OverrideUrl=key=>Url(WardrobePackService.Find(key),source);
            Check(!WardrobePackService.Installed("ron-26dj")&&WardrobePackService.Installed("ron-fate-hf"),"Fresh client has optional wins missing and Fate builtin");
            client.Lobby.DesignPreviewGardenEntry();yield return Wait(25);client.LobbyOpenSettings();var settings=(NativeSettingsUi)typeof(RiichiClient).GetField("nativeSettings",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(client);settings.Tab=2;yield return Wait();settings.ReviewPress="resource-page-wardrobe";yield return Wait(5);Check(settings.ReviewPress==null,"Settings contains wardrobe-resource subpage");yield return Shot("settings-wardrobe-resources");client.LobbyCloseSettings();
            client.Lobby.PreviewWardrobe("winEffect");yield return Wait();client.Lobby.ValidationPress("dress-item-ron-tornado");yield return Wait();Check(ui.ModalOpen,"Selecting a missing outfit opens its download dialog");yield return Shot("outfit-single-download");yield return Press("deco-prompt-cancel");
            ui.Open("winEffect");yield return Shot("win-category-resources");ui.Ask("ron-26dj");yield return Press("deco-prompt-download");yield return Until(()=>service.Busy&&service.Progress>.06f&&service.Progress<.95f,"Partial transfer");string partialKey=service.DownloadKey;var partial=WardrobePackService.Find(partialKey);yield return Shot("download-progress");service.Cancel();yield return Until(()=>!service.Busy,"Cancel completes");string part=WardrobePackService.FilePath(partial)+".part";Check(File.Exists(part)&&new FileInfo(part).Length>0&&!File.Exists(WardrobePackService.FilePath(partial)+".ok"),"Cancel retains partial bytes without receipt");yield return Until(()=>!WardrobePackService.Pinned(partialKey),"Transfer pin released");yield return Download("ron-26dj");Check(source.RangeRequests>0,"Resume sends an actual HTTP Range request");
            var selected=WardrobePackService.ForItem("ron-26dj");WardrobePackService.Pin(selected.key);Check(!WardrobePackService.DeleteItem("ron-26dj",out _),"Active resource pin prevents deletion");WardrobePackService.Unpin(selected.key);
            if(selected.dependencies.Length>0)Check(!WardrobePackService.DeletePack(selected.dependencies[0],out _),"Installed parent protects shared dependency");
            WardrobeSelection.Save(new[]{new KeyValuePair<string,string>("winEffect","ron-26dj")});Check(WardrobePackService.DeleteItem("ron-26dj",out _),"Unused optional win can be deleted");Check(WardrobeSelection.Get("winEffect").id=="win-default","Deletion restores the offline base selection");
            relay=new CharacterPackShareServer{Enabled=true};relay.SetEntries(WardrobePackService.All.Where(p=>!p.builtin).Select(p=>new CharacterPackShareServer.Entry{key=p.key,hash=p.sha256,bytes=p.bytes,url=Url(p,source),wardrobe=true}));service.OverrideUrl=key=>Url(WardrobePackService.Find(key),relay);yield return Download("ron-26dj");Check(relay.Requests>0,"Wardrobe download traverses actual HTTP host relay");
            var bad=WardrobePackService.ForItem("ron-kaguya");string badFile=WardrobePackService.FilePath(bad);Directory.CreateDirectory(Path.GetDirectoryName(badFile));using(var f=File.Create(badFile+".part"))f.SetLength(bad.bytes);service.DownloadItem("ron-kaguya");yield return Until(()=>!service.Busy,"Reject corruption");Check(!WardrobePackService.Installed("ron-kaguya")&&!File.Exists(badFile+".ok")&&service.Error.Contains("校验失败"),"Same-size corrupt content is rejected before install");yield return Download("ron-kaguya");
            ui.Close();source.ReviewChunkDelayMs=0;Check(errors.Count==0,"Download, resume, deletion and relay emit no Unity errors");
        }
        IEnumerator InstallAndVerify(){
            foreach(var p in WardrobePackService.All.Where(p=>!p.builtin)){
                string sourceFile=Bundle(p);Check(File.Exists(sourceFile)&&new FileInfo(sourceFile).Length==p.bytes&&WardrobePackService.HashFile(sourceFile)==p.sha256,"Built bundle size and SHA: "+p.key);string dest=WardrobePackService.FilePath(p);Directory.CreateDirectory(Path.GetDirectoryName(dest));if(!File.Exists(dest))File.Copy(sourceFile,dest);File.WriteAllText(dest+".ok",p.sha256);
            }
            WardrobePackService.ResetForReview();
            int checkedAssets=0;foreach(var item in WardrobePackService.Directory.items){
                Check(WardrobePackService.Installed(item.id),"Installed full item closure: "+item.id);yield return WardrobePackService.Preload(new[]{item.id});
                var p=WardrobePackService.ForItem(item.id);if(p.builtin)continue;
