                yield return null;
            }
            Debug.Log("WARDROBE BUNDLE ADDRESS PASS "+checkedAssets);
        }
        RoomView View(WardrobeItem item,string kind,int viewer){var view=JsonUtility.FromJson<RoomView>(File.ReadAllText(repo+"/build/unity-smoke/win-4-"+kind+"-0-0.json"));view.you=viewer;view.resourceSetup=null;view.dealtAt=0;view.openingHand=new string[0];view.audioRoom="r22-"+item.id+kind+viewer;foreach(var player in view.players){player.auto=false;player.character="yiji";player.skin=400101;player.wardrobe=new WardrobeLoadout{hand="hand-human",headFrame="headframe_default",cloth="cloth-default",tileFace="mjpface_default",tileBack="mjp_default",winEffect=item.id,riichiEffect="riichi-blue",stick="stick-default"};}return view;}
        IEnumerator Use(RoomView view){client.ShowValidationFixture(view);client.ValidationTableOnly=true;client.ValidationIntro.Reset();fx.Reset();fx.ValidationFreeze=true;fx.ValidationSequentialClock=true;fx.ValidationTime=0;fx.Accept(view);yield return Wait(2);var d=view.result.details[0];var item=new PublicSound{id=1,seat=d.seat,from=d.from,tile=d.tile,kind=d.ron?"ron":"tsumo",winSource=d.winSource};typeof(TableEffects).GetMethod("SpawnWin",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(fx,new object[]{item,-.1f});yield return Wait(1);}
