            if(mode=="spot")wins=wins.Where(i=>new[]{"ron-liyang","ron-24imas","ron-flame","ron-fate-hf","win-default","ron-26dj"}.Contains(i.id)).ToArray();
            foreach(var item in wins){yield return WardrobePackService.Preload(new[]{item.id});foreach(string kind in new[]{"ron","tsumo"})for(int viewer=0;viewer<4;viewer++){
                yield return Use(View(item,kind,viewer));var win=fx.ValidationWin;Check(win!=null,"Win instantiates: "+item.id+kind+viewer);bool particles=false,visible=false;
                foreach(float age in viewer==0?new[]{.05f,.6f,1.3f,3.5f,5.7f}:new[]{.05f,.6f,1.3f}){if(win==null)break;fx.ValidationTime=age;yield return Wait(1);if(win==null)break;particles|=win.ParticleCount>0;visible|=win.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.isVisible);Check(win.GetComponentsInChildren<Renderer>(true).All(r=>!float.IsNaN(r.bounds.center.x)&&!float.IsInfinity(r.bounds.center.x)),"Finite animated geometry: "+item.id+kind+viewer+" age "+age);}
                Check(particles||win?.MeshLayerCount>0,"Particle or mesh content plays: "+item.id+kind+viewer);Check(visible,"Effect reaches game camera: "+item.id+kind+viewer);
                if(mode=="spot"&&viewer==0&&win!=null&&win.SourceResultDelay.HasValue){float lead=kind=="ron"?2:2.8f-SourcePlaybackContracts.HandAction(WardrobeCatalog.Find("hand-human"),"Zimo").release-.1f;float end=lead+win.SourceResultDelay.Value;fx.ValidationTime=end-.01f;yield return Wait(1);Check(fx.ShowWinPresentation,"Original result delay retains table before threshold: "+item.id+kind);fx.ValidationTime=end+.01f;yield return Wait(1);Check(!fx.ShowWinPresentation,"Original result delay releases table independently of prefab: "+item.id+kind);Check(fx.ValidationWin!=null,"Six-second prefab cleanup remains independent: "+item.id+kind);}
