                if(viewer==0){fx.ValidationTime=9;yield return Wait(2);Check(fx.ValidationWin==null,"Win lifetime releases table: "+item.id+kind);}fx.Reset();report.cases++;
            }Debug.Log("WIN R22 CASES "+item.id+" completed="+report.cases);}
            Check(errors.Count==0,"All win views have no Unity runtime errors");
        }
        void BeginEncoder(){var start=new System.Diagnostics.ProcessStartInfo{FileName="C:/Users/Rtyu3221/.cache/codex-runtimes/codex-primary-runtime/dependencies/python/python.exe",Arguments="-X utf8 \""+repo+"/scripts/encode-game-capture.py\" --output \""+output+"/all-wins-r22-2x.mp4\" --width "+Screen.width+" --height "+Screen.height+" --fps 24",UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};encoder=new System.Diagnostics.Process{StartInfo=start};encoder.OutputDataReceived+=(s,e)=>{if(e.Data!=null)File.AppendAllText(output+"/encoder.log",e.Data+"\n");};encoder.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)File.AppendAllText(output+"/encoder.log",e.Data+"\n");};encoder.Start();encoder.BeginOutputReadLine();encoder.BeginErrorReadLine();pipe=encoder.StandardInput.BaseStream;Time.captureFramerate=24;}
        IEnumerator Frame(){yield return new WaitForEndOfFrame();var image=ScreenCapture.CaptureScreenshotAsTexture();var pixels=image.GetPixels32();if(rgba==null||rgba.Length!=pixels.Length*4)rgba=new byte[pixels.Length*4];for(int i=0;i<pixels.Length;i++){int at=i*4;rgba[at]=pixels[i].r;rgba[at+1]=pixels[i].g;rgba[at+2]=pixels[i].b;rgba[at+3]=pixels[i].a;}pipe.Write(rgba,0,rgba.Length);Destroy(image);report.frames++;}
        IEnumerator Gallery(){BeginEncoder();int number=0;foreach(var item in WardrobeCatalog.Items("winEffect")){yield return WardrobePackService.Preload(new[]{item.id});yield return Use(View(item,"ron",0));caption="和牌特效 · 2 倍速预览   "+(++number)+" / 60    "+item.name;report.clips.Add(new Clip{id=item.id,name=item.name,at=report.frames/24f});for(int frame=0;frame<74;frame++){fx.ValidationTime=frame/12f;yield return Frame();}fx.Reset();}caption=null;pipe.Close();encoder.WaitForExit();Check(encoder.ExitCode==0,"Video encoder completes");encoder.Dispose();encoder=null;pipe=null;Time.captureFramerate=0;}
        void OnGUI(){if(caption==null)return;GUI.depth=-300;var old=GUI.color;GUI.color=new Color(.025f,.035f,.07f,.9f);GUI.DrawTexture(new Rect(0,0,Screen.width,52),Texture2D.whiteTexture);GUI.color=Color.white;GUI.Label(new Rect(20,4,Screen.width-40,44),caption,new GUIStyle(GUI.skin.label){font=Resources.Load<Font>("Majsoul/Font/game"),fontSize=26,alignment=TextAnchor.MiddleCenter});GUI.color=old;}
